<<script>>$(document).one(':passagerender', function (ev) {
		$(ev.content).find("[name='radiobutton-gender']").on("change", function (event) {
			$.wiki('<<if $upbring is "attwhore" and $gender is "Guy">><<set $upbring to "loud">><</if>><<if $upbring is "loud" and $gender is "Girl">><<set $upbring to "attwhore">><</if>><<redo "up">><<redo "partner">>');
            if (State.variables.upbring === "attwhore") { 
            	$("#upbring1").trigger("click");
            } else if (State.variables.upbring === "loud") {
            	$("#upbring2").trigger("click");
            }
		});
        $(ev.content).find("[name='radiobutton-upbring']").on("change", function (event) {
          $.wiki("<<redo 'partner'>>");
        });
	});<</script>>
